"""Summarize only files generated by this run; no directory enumeration."""
import os, json
from pathlib import Path
os.environ['OPENBLAS_NUM_THREADS']='1'
os.environ['MPLCONFIGDIR']=str(Path('results/mplconfig').resolve())
import numpy as np
from d2 import entropy_fit, dump

def read(path):
    return json.loads(Path(path).read_text())

def intercept(L,y,powers):
    X=np.column_stack([np.ones(len(L))]+[L**(-p) for p in powers])
    return np.linalg.lstsq(X,y,rcond=None)[0]

def estimates(rows):
    L=np.array([r['L'] for r in rows],float)
    c=np.array([r['c'] for r in rows]); E=np.array([r['E0'] for r in rows])
    mv=np.array([np.mean([s['selected']['c_MV'] for s in r['stress']]) for r in rows])
    vel=np.array([np.mean([s['velocity'] for s in r['stress']]) for r in rows])
    results=[]
    for start in (8,10,12,14,16):
        mask=L>=start
        if sum(mask)<4: continue
        LL=L[mask]; ee=intercept(LL,E[mask]/LL,[2,4]); vv=intercept(LL,vel[mask],[2,4])[0]
        results.append(dict(min_L=start,c_energy=float(-6*ee[1]/(np.pi*vv)),v_extrap=float(vv),
                            c_MV=float(intercept(LL,mv[mask],[2,4])[0]),
                            c_entropy_1L=float(intercept(LL,c[mask],[1])[0]),
                            c_entropy_1L2=float(intercept(LL,c[mask],[2])[0])))
    def summarize(key,preferred=14):
        rows2=[r for r in results if r['min_L']>=10]
        central=next((r[key] for r in rows2 if r['min_L']==preferred),rows2[-1][key])
        return dict(value=central,fit_window_spread=max(abs(r[key]-central) for r in rows2))
    return dict(fits=results,energy=summarize('c_energy'),MV=summarize('c_MV'),
                entropy=summarize('c_entropy_1L'),
                entropy_model_spread=max(abs(r['c_entropy_1L2']-summarize('c_entropy_1L')['value']) for r in results))

cal=read('results/calibration_fixed.json'); stats={}
lines=['# Calibration table','',
       'Raw estimates use the largest available L. Quoted uncertainties are conservative sensitivity scales, the larger of the window/model spread and the final-size-to-extrapolation correction. They are not confidence intervals or rigorous error bounds. The Fourier density splits the field equally between sites.', '',
       '| Chain | expected c | L | entropy c_eff | entropy bulk | c_MV | c_E, raw v_T | extrapolated c_S | extrapolated c_MV | extrapolated c_E |',
       '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for name,item in cal.items():
    rows=item['rows']; r=rows[-1]; es=estimates(rows); stats[name]=es
    bulk=entropy_fit(r['entropy'],r['L'],max(2,r['L']//4))['c']
    rawmv=np.mean([s['selected']['c_MV'] for s in r['stress']])
    se=max(es['entropy']['fit_window_spread'],es['entropy_model_spread'],abs(r['c']-es['entropy']['value']))
    raw=dict(MV=rawmv,energy=item['energy_fit']['c_energy'])
    fmt=lambda key: f"{es[key]['value']:.5f} ± {max(es[key]['fit_window_spread'],abs(raw[key]-es[key]['value'])):.5f}"
    lines.append(f"| {name} | {item['parameters']['expected']} | {r['L']} | {r['c']:.6f} | {bulk:.6f} | {rawmv:.6f} | {item['energy_fit']['c_energy']:.6f} | {es['entropy']['value']:.5f} ± {se:.5f} | {fmt('MV')} | {fmt('energy')} |")
lines += ['', 'The quoted spreads do not include an unknown asymptotic correction law. In particular, logarithmic corrections in Heisenberg are not controlled by these polynomial fits. The benchmark value c=1 remains consistent with its observed drift.', '',
          'All off-diagonal exchange entries vanish in these benchmarks. Couplings use Pauli matrices.', '',
          '| chain | (Jxx, Jyy, Jzz) | field |', '|---|---|---|']
for name,item in cal.items():
    par=item['parameters']; lines.append(f"| {name} | {tuple(float(x) for x in np.diag(par['J']))} | {tuple(par['field'])} |")
lines += ['',
          'The lowest-momentum velocity fails for Ising. Its q=1 estimate approaches 2.25, whereas the stress velocity approaches 2. Using the former as v would underestimate c.', '',
          'The literal left-site field density also fails the largest-overlap Ising prescription. See methods.md and results/density_check.json.']
Path('calibration.md').write_text('\n'.join(lines)+'\n'); dump('results/calibration_extrapolation.json',stats)

sources=['results/best_opt.json','results/candidate_refined.json','results/candidate854.json',
         'results/candidate628.json','results/candidate871.json','results/ferromagnet_half.json',
         'results/extra_candidates.json','results/extra_candidates_b.json','results/extra_candidates_c.json',
         'results/structured_refined.json','results/critical_refined.json','results/optimized16_refined.json',
         'results/max_raw_refined.json','results/structured_dm_refined.json']
allc={}
for path in sources:
    if Path(path).exists(): allc.update(read(path))
lines=['# Candidate diagnostics','',
       'These are finite-size statistics, not assigned central charges. Each detailed generic row searches all ground-state momentum sectors. The two stress columns are the independently selected largest-overlap levels.', '',
       '| ID | L | m0 | c_eff | cut-window spread | adjacent-size drift | c_MV,+ | c_MV,- | v_q1,+ | v_q1,- | v_T,+ | v_T,- |',
       '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for key,item in allc.items():
    rows=item['rows']
    for i,r in enumerate(rows):
        cc=[r['c'],entropy_fit(r['entropy'],r['L'],3)['c'],entropy_fit(r['entropy'],r['L'],max(2,r['L']//4))['c']]
        delta=abs(r['c']-rows[i-1]['c']) if i else float('nan')
        a,b=r['stress']
        lines.append(f"| {key} | {r['L']} | {r['momentum']} | {r['c']:.6f} | {max(cc)-min(cc):.6f} | {delta:.6f} | {a['selected']['c_MV']:.6f} | {b['selected']['c_MV']:.6f} | {r['v_q1_plus']:.6f} | {r['v_q1_minus']:.6f} | {a['velocity']:.6f} | {b['velocity']:.6f} |")
    lines += []
lines += ['', '## Parameters', '']
for key,item in allc.items():
    lines += [f'### {key}', '', '```json', json.dumps(item['parameters'],indent=2), '```', '']
Path('candidates.md').write_text('\n'.join(lines)+'\n')

scans={}
for name in ('global_scan','boundary_scan','optimization','optimization16','shortlist','global_shortlist'):
    path='results/'+name+'.json'
    if not Path(path).exists(): continue
    data=read(path); ok=[r for r in data if 'c_eff' in r]
    scans[name]=dict(count=len(data),failed=len(data)-len(ok),above_one=sum(r['c_eff']>1 for r in ok),
                     max_c_eff=max(ok,key=lambda r:r['c_eff']),max_score=max(ok,key=lambda r:r['score']))
dump('results/search_summary.json',scans)
slines=['# Scan summary','',
        'Maxima in this table are raw entropy slopes at the larger screening size, not central charges. Parameter matrices and all individual rows are in the named JSON files.', '',
        '| scan | family | samples | larger L | largest c_eff | point |',
        '|---|---|---:|---:|---:|---|']
for name in ('global_scan','boundary_scan'):
    data=read('results/'+name+'.json')
    families=sorted({r['family'] for r in data})
    for family in families:
        rr=[r for r in data if r['family']==family and 'c_eff' in r]
        top=max(rr,key=lambda r:r['c_eff'])
        slines.append(f"| {name} | {family} | {len(rr)} | {top['rows'][-1]['L']} | {top['c_eff']:.6f} | {top['id']} |")
if Path('results/velocity_screen.json').exists():
    v=read('results/velocity_screen.json')
    slines += ['', 'The second-stage ranking includes drift of the lowest finite-momentum excitation velocity. The leading entries are below. Two-size exponents are heuristic diagnostics.', '',
               '| point | c_eff | z from first nonzero gap | z from q=1 gap | ranking score |',
               '|---|---:|---:|---:|---:|']
    for r in sorted(v,key=lambda r:r['score2'],reverse=True)[:15]:
        slines.append(f"| {r['id']} | {r['c_eff']:.6f} | {r['z_gap']:.4f} | {r['z_q1']:.4f} | {r['score2']:.4f} |")
Path('scan_summary.md').write_text('\n'.join(slines)+'\n')

try:
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,3,figsize=(13,3.7),layout='constrained')
    for name,item in cal.items():
        rr=item['rows']; L=[r['L'] for r in rr]
        axes[0].plot(L,[r['c'] for r in rr],'.-',label=name)
    axes[0].axhline(1,color='gray',lw=.7); axes[0].axhline(.5,color='gray',lw=.7)
    axes[0].set(title='Calibration, raw entropy slope',xlabel='L',ylabel='c_eff'); axes[0].legend(fontsize=7)
    for key in ('830','854','1256','opt16_121','1004'):
        if key not in allc: continue
        rr=allc[key]['rows']; L=[r['L'] for r in rr]
        axes[1].plot(L,[r['c'] for r in rr],'.-',label=key)
    axes[1].axhline(1,color='gray',lw=.7); axes[1].set(title='Largest small-size candidates',xlabel='L',ylabel='c_eff'); axes[1].legend(fontsize=7)
    for key in ('XXZ_-0.99','XXZ_-0.999'):
        if key not in allc: continue
        rr=allc[key]['rows']; L=[r['L'] for r in rr]
        axes[2].plot(L,[r['c'] for r in rr],'.-',label=key+' entropy')
        axes[2].plot(L,[r['stress'][0]['selected']['c_MV'] for r in rr],'.--',label=key+' MV')
    axes[2].axhline(1,color='gray',lw=.7); axes[2].set(title='Ferromagnetic crossover',xlabel='L',ylabel='finite-size estimator'); axes[2].legend(fontsize=7)
    fig.savefig('results/diagnostics.png',dpi=160); fig.savefig('results/diagnostics.svg')
except ImportError as exc:
    print('Optional plot unavailable:',exc)
print('Wrote calibration.md, candidates.md, summaries and optional plot.')
